# Разметка фильтра OCFilter на живом сайте — только читает. Показывает
# подключённые файлы стилей и скриптов модуля, где в странице стоит
# буквальный «&amp;nbsp;» и дерево блока фильтра: теги, id и классы,
# по два одинаковых соседа (остальные — «... more»), не больше 90 строк.
( U=https://stroigeroi.ru/dreli-shurupoverty-perforatory; F=$HOME/ocf-check.html; curl -s "$U" -o "$F" || exit 1; echo "-- files"; grep -oE '(href|src)="[^"]*ocfilter[^"]*"' "$F" | sort -u; echo "-- nbsp"; grep -oE '.{0,40}&amp;nbsp;.{0,12}' "$F" | head -4; echo "-- markup"; php -r 'libxml_use_internal_errors(true); $d = new DOMDocument(); $d->loadHTML("<?xml encoding=\"utf-8\"?>" . file_get_contents($argv[1])); $x = new DOMXPath($d); $root = $x->query("//*[contains(@id,\"ocfilter\") or contains(@class,\"ocfilter\") or contains(@class,\"ocf-\")]")->item(0); if (!$root) { echo "no ocfilter block\n"; exit(1); } $n = 0; $walk = function ($node, $depth) use (&$walk, &$n) { $count = array(); foreach ($node->childNodes as $c) { if ($n > 90) return; $pad = str_repeat("  ", $depth); if ($c->nodeType == XML_TEXT_NODE) { $t = preg_replace("/\s+/u", " ", trim($c->textContent)); if ($t !== "") { echo $pad, "\"", mb_substr($t, 0, 50), "\"\n"; $n++; } continue; } if ($c->nodeType != XML_ELEMENT_NODE) continue; $s = $c->nodeName . ($c->getAttribute("id") ? "#" . $c->getAttribute("id") : "") . ($c->getAttribute("class") ? "." . preg_replace("/\s+/", ".", trim($c->getAttribute("class"))) : ""); $count[$s] = isset($count[$s]) ? $count[$s] + 1 : 1; if ($count[$s] > 2) { if ($count[$s] == 3) { echo $pad, "... more ", $s, "\n"; $n++; } continue; } if (in_array($c->nodeName, array("script", "style", "svg"))) { echo $pad, "<", $c->nodeName, ">\n"; $n++; continue; } $extra = ""; foreach (array("type", "name", "value", "data-toggle", "style") as $a) if ($c->getAttribute($a) !== "") $extra .= " " . $a . "=" . mb_substr($c->getAttribute($a), 0, 30); echo $pad, $s, $extra, "\n"; $n++; $walk($c, $depth + 1); } }; echo $root->nodeName, " #", $root->getAttribute("id"), " .", $root->getAttribute("class"), "\n"; $walk($root, 1);' "$F"; rm -f "$F" )
